// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 depositAmount, address depositor) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        vm.assume(depositor != address(0));

        HeavyFallback recv = new HeavyFallback();

        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        vm.deal(address(recv), depositAmount);
        vm.prank(address(recv));
        c.deposit{value: depositAmount}();

        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        vm.prank(address(recv));
        bool okRecv;
        try c.withdrawAll() {
            okRecv = true;
        } catch {
            okRecv = false;
        }

        assertTrue(okRecv);
    }
}

contract HeavyFallback {
    fallback() external payable {
        for (uint i = 0; i < 1000; i++) {
            uint x = i * i;
            x;
        }
    }
}
